import { Router, Request, Response, NextFunction } from 'express';
import multer from 'multer';
import { randomUUID } from 'crypto';
import { storage } from './storage';

const upload = multer({ limits: { fileSize: 10 * 1024 * 1024 } });
export const uploadsRouter = Router();
interface UploadResult {
  id: string;
  size: number;
  url: string;
}

uploadsRouter.post(
  '/uploads',
  upload.single('file'),
  async (req: Request, res: Response<UploadResult | { error: string }>, next: NextFunction) => {
    try {
      if (!req.file) {
        return res.status(400).json({ error: 'No file provided' });
      }
      const id = randomUUID();
      const url = await storage.put(`uploads/${id}`, req.file.buffer, req.file.mimetype);
      res.status(201).json({ id, size: req.file.size, url });
    } catch (err) {
      next(err);
    }
  }
);

async function withRetry(fn, attempts = 3, delayMs = 200) {
  for (let i = 0; i < attempts; i++) {
    try {
      return await fn();
    } catch (err) {
      if (i === attempts - 1) throw err;
      await new Promise((resolve) => setTimeout(resolve, delayMs * 2 ** i));
    }
  }
}

const express = require('express');
const Redis = require('ioredis');

const redis = new Redis(process.env.REDIS_URL);
const app = express();
app.use(express.json());

app.post('/scores', async (req, res) => {
  const { player, score } = req.body;
  if (!player || typeof score !== 'number') {
    return res.status(400).json({ error: 'player and numeric score are required' });
  }
  await redis.zadd('leaderboard:weekly', 'GT', score, player);
  const rank = await redis.zrevrank('leaderboard:weekly', player);
  res.status(201).json({ player, score, rank: rank + 1 });
});

app.get('/scores/top', async (req, res) => {
  const limit = Math.min(parseInt(req.query.limit, 10) || 10, 100);
  const rows = await redis.zrevrange('leaderboard:weekly', 0, limit - 1, 'WITHSCORES');
  const top = [];
  for (let i = 0; i < rows.length; i += 2) {
    top.push({ player: rows[i], score: Number(rows[i + 1]) });
  }
  res.json(top);
});

app.listen(3000, () => console.log('leaderboard listening on :3000'));

