class UploadViewModel(private val uploader: FileUploader) : ViewModel() {

    private val _state = MutableStateFlow<UploadState>(UploadState.Pending)
    val state: StateFlow<UploadState> = _state.asStateFlow()

    fun upload(file: File) {
        viewModelScope.launch {
            _state.value = UploadState.Uploading(0)
            try {
                val url = uploader.send(file) { sent, total ->
                    _state.value = UploadState.Uploading((sent * 100 / total).toInt())
                }
                _state.value = UploadState.Done(url)
            } catch (e: IOException) {
                _state.value = UploadState.Failed(e)
            }
        }
    }
}

sealed interface UploadState {
    data object Pending : UploadState
    data class Uploading(val percent: Int) : UploadState
    data class Done(val url: String) : UploadState
    data class Failed(val reason: Throwable) : UploadState
}

