use std::collections::HashMap;
use tokio::sync::{broadcast, RwLock};

#[derive(Clone, Debug)]
pub struct ChatMessage {
    pub room: String,
    pub author: String,
    pub body: String,
}

#[derive(Default)]
pub struct Hub {
    rooms: RwLock<HashMap<String, broadcast::Sender<ChatMessage>>>,
}

impl Hub {
    pub async fn subscribe(&self, room: &str) -> broadcast::Receiver<ChatMessage> {
        let mut rooms = self.rooms.write().await;
        rooms
            .entry(room.to_owned())
            .or_insert_with(|| broadcast::channel(256).0)
            .subscribe()
    }

    pub async fn publish(&self, msg: ChatMessage) -> usize {
        let rooms = self.rooms.read().await;
        rooms.get(&msg.room).map_or(0, |tx| tx.send(msg).unwrap_or(0))
    }
}

function Restart-StalledService {
    [CmdletBinding(SupportsShouldProcess)]
    param(
        [Parameter(Mandatory, ValueFromPipeline)]
        [string[]]$Name,

        [int]$TimeoutSeconds = 30
    )

    process {
        foreach ($serviceName in $Name) {
            $service = Get-Service -Name $serviceName -ErrorAction SilentlyContinue
            if (-not $service) {
                Write-Warning "Service '$serviceName' was not found."
                continue
            }

            if ($service.Status -ne 'Running' -and $PSCmdlet.ShouldProcess($serviceName, 'Restart')) {
                Restart-Service -Name $serviceName -Force
                $service.WaitForStatus('Running', [TimeSpan]::FromSeconds($TimeoutSeconds))
                Write-Verbose "Restarted $serviceName"
            }
        }
    }
}

